{
  "decision-serialize-confirmed-specimen-labels": "WITH agreed AS (SELECT specimen, MIN(label) AS label, MIN(source_id) AS source_id FROM label_slip WHERE label IS NOT NULL GROUP BY specimen HAVING COUNT(DISTINCT label COLLATE BINARY) = 1), records AS (SELECT '\"' || replace(specimen, '\"', '\"\"') || '\",\"' || replace(label, '\"', '\"\"') || '\",\"' || replace(source_id, '\"', '\"\"') || '\"' || char(10) AS line FROM agreed ORDER BY specimen COLLATE BINARY) SELECT 'specimen,label,source_id' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_text FROM records",
  "decision-settle-capped-royalty-and-advance": "WITH earned AS (SELECT license_id, opening_advance_cents, minimum_cash_cents, MIN(royalty_cap_cents, MIN(sales_cents, 10000) / 10 + MAX(sales_cents - 10000, 0) / 5) AS capped_royalty_cents FROM license_quarter), recovered AS (SELECT *, MIN(opening_advance_cents, capped_royalty_cents) AS recouped_cents FROM earned) SELECT license_id, capped_royalty_cents, recouped_cents, MAX(capped_royalty_cents - recouped_cents, minimum_cash_cents) AS cash_due_cents, opening_advance_cents - recouped_cents AS closing_advance_cents FROM recovered ORDER BY license_id",
  "decision-settle-monthly-solar-export-credit": "WITH charges AS (SELECT b.bill_month, b.imported_kwh * n.buy_cents AS import_cents, b.exported_kwh * n.sell_cents AS export_cents, n.fixed_cents, n.source_id FROM bill_meter AS b JOIN tariff_notice AS n ON n.effective_month = (SELECT MAX(t.effective_month) FROM tariff_notice AS t WHERE t.effective_month <= b.bill_month)), credits AS (SELECT *, MIN(import_cents, export_cents) AS applied_credit_cents FROM charges) SELECT bill_month, import_cents, applied_credit_cents, import_cents - applied_credit_cents + fixed_cents AS due_cents, source_id FROM credits ORDER BY bill_month",
  "decision-seven-day-repeat-contact-cohort": "WITH ranked AS (SELECT ticket_code, queue_code AS intake_queue, contact_day AS intake_day, ROW_NUMBER() OVER (PARTITION BY ticket_code ORDER BY contact_day, contact_seq) AS contact_rank FROM ticket_contacts WHERE ticket_code IS NOT NULL) SELECT r.intake_queue, SUM(EXISTS (SELECT 1 FROM ticket_contacts AS c WHERE c.ticket_code = r.ticket_code AND c.contact_day BETWEEN r.intake_day + 1 AND r.intake_day + 7)) AS repeat_tickets, COUNT(*) AS eligible_tickets FROM ranked AS r WHERE r.contact_rank = 1 AND r.intake_day + 7 <= 20 GROUP BY r.intake_queue ORDER BY r.intake_queue"
}
